function fail(target:HTMLElement,error:unknown){target.innerHTML=alert('We couldn’t complete that request',errorMessage(error),'danger')+link('Try again',location.pathname+location.search+location.hash);}
function action(id:string,task:()=>void,target:ParentNode=root){target.querySelector<HTMLButtonElement>('#'+id)?.addEventListener('click',()=>{Promise.resolve().then(task).catch(errorToast);});}
function openForm(title:string,body:string,task:(data:any,element:HTMLDialogElement)=>Promise<void>,label='Save changes',drawer=true,errorLink?:{label:string;href:string}){const element=dialog(title,form(body,label),drawer);element.querySelector('[data-cancel]')!.addEventListener('click',()=>element.close());formSubmit(element.querySelector('form')!,data=>task(data,element),errorLink);return element;}
function loaded(content:string){return `<div class="pw-section-body pw-stagger">${content}</div>`;}
function setPrimary(label:string,handler:()=>void,symbol='plus'){const target=root.querySelector<HTMLElement>('#pw-primary')!;target.innerHTML=button(label,'page-primary','primary',symbol);primaryAction=handler;action('page-primary',handler);}
function readAccess(key:string){return can(identity,modulePermission(key));}
function writeAccess(key:string){return can(identity,modulePermission(key),true);}
function errorToast(error:unknown){toast(errorMessage(error));}
function menu(open:boolean){const sidebar=root.querySelector<HTMLElement>('.pw-sidebar');if(!sidebar)return;document.body.classList.toggle('pw-drawer-open',open);const small=matchMedia('(max-width:1023px)').matches;sidebar.inert=small&&!open;sidebar.setAttribute('aria-hidden',String(small&&!open));root.querySelector('#pw-mobile-menu')?.setAttribute('aria-expanded',String(open));const scrim=root.querySelector<HTMLElement>('#pw-scrim');if(scrim)scrim.hidden=!open;if(small){document.body.style.overflow=open?'hidden':'';if(open)(sidebar.querySelector('button') as HTMLElement)?.focus();}}
let bound=false;
function globalBindings(){if(bound)return;bound=true;window.addEventListener('resize',()=>menu(false));document.addEventListener('keydown',event=>{if(!document.body.classList.contains('pw-body'))return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchModules();}if(event.key==='Escape'&&!document.querySelector('dialog[open]')){menu(false);(root.querySelector('#pw-mobile-menu') as HTMLElement)?.focus();}if(event.key==='Tab'&&document.body.classList.contains('pw-drawer-open')&&!document.querySelector('dialog[open]')){const links=Array.from(root.querySelectorAll<HTMLElement>('.pw-sidebar a,.pw-sidebar button'));const first=links[0],last=links.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});}
function searchModules(){const items=(admin?adminModules:studentModules).filter(item=>!admin||readAccess(item[0]));const element=dialog('Find your next step',`${field('search','Search pages','','search')}<nav id="pw-search-results" class="pw-stack"></nav>`);const input=element.querySelector<HTMLInputElement>('input')!;const render=()=>{element.querySelector('#pw-search-results')!.innerHTML=items.filter(item=>item[1].toLowerCase().includes(input.value.toLowerCase())).map(item=>link(item[1],(admin?'/admin':'/portal')+'#'+item[0],'',item[2])).join('')||empty('No matching pages','Try searching for students, fees or messages.');element.querySelectorAll('a').forEach(a=>a.onclick=()=>element.close());};input.oninput=render;render();input.focus();}
async function signOut(all=false){if(all&&!await confirm('Sign out of all devices?','Your active sessions on all browsers and devices will end.','Sign out everywhere'))return;try{await api(all?'/auth/logout-all':'/auth/logout','POST',{});location.assign(admin?'/admin/login':'/student/login');}catch(error){errorToast(error);}}
function shell(key:string,profile?:any){const modules=admin?adminModules:studentModules;const items=modules.filter(item=>!admin||readAccess(item[0]));const page=modules.find(item=>item[0]===key)||(key==='consultations'?['consultations','Adviser appointments','calendar-days','','Find a time to talk about your next step.']:['profile','Your profile','user-round','','Your contact details and personal information.']);const groups=admin?['Overview','People','Money','Campus','Content','System']:[''];const displayName=admin?'School administrator':profile?.firstName||'Student';document.body.classList.add('pw-body','pw');document.body.classList.toggle('pw-student',!admin);document.body.classList.toggle('pw-collapsed',localStorage.getItem('pw-sidebar-collapsed')==='true'&&matchMedia('(min-width:1024px)').matches);document.title=page[1]+' | NewworldPathway';root.innerHTML=`<div class="pw-layout"><button class="pw-scrim" id="pw-scrim" hidden aria-label="Close navigation"></button><aside class="pw-sidebar" id="pw-sidebar" aria-label="${admin?'Admin':'Student'} navigation"><button class="pw-button pw-mobile-only" id="pw-close-menu">${icon('x')}Close menu</button><a class="pw-brand" href="/" aria-label="NewworldPathway home"><img src="/assets/school-logo.png" alt="School crest" width="40" height="48"><span><strong>NewworldPathway</strong><small>${admin?'School workspace':'Your university journey'}</small></span></a><nav>${groups.map(group=>{const children=items.filter(item=>item[3]===group);return children.length?`<div class="pw-nav-group">${group?`<p class="pw-nav-label">${group}</p>`:''}${children.map(item=>`<a class="pw-nav-link" href="#${item[0]}" title="${esc(item[1])}" ${item[0]===key?'aria-current="page"':''}>${icon(item[2])}<span class="pw-nav-text">${esc(item[1])}</span></a>`).join('')}</div>`:'';}).join('')}</nav><footer class="pw-sidebar-footer"><a class="pw-nav-link" href="https://wa.me/2348136037074" target="_blank" rel="noopener" title="Need help? Chat on WhatsApp">${icon('message-circle')}<span class="pw-nav-text">Need help? Let’s talk</span></a><a class="pw-nav-link" href="/" title="Public website">${icon('external-link')}<span class="pw-nav-text">Public website</span></a><p>New World Emerald Private School<br>Kubwa, Abuja</p></footer></aside><div class="pw-workspace"><header class="pw-topbar"><div class="pw-row"><button class="pw-button pw-icon-button pw-desktop-only" id="pw-collapse" aria-label="Collapse sidebar">${icon('panel-left-close')}</button><button class="pw-button pw-icon-button pw-mobile-only" id="pw-mobile-menu" aria-controls="pw-sidebar" aria-expanded="false" aria-label="Open navigation">${icon('menu')}</button><button class="pw-button quiet pw-search" id="pw-global-search">${icon('search')}<span>Search your workspace</span><kbd>⌘ / Ctrl K</kbd></button></div><div class="pw-top-actions">${admin?`<span class="pw-badge">${esc((identity.adminRole||'Staff').replaceAll('_',' '))}</span>`:''}<button class="pw-button pw-icon-button" id="pw-notifications" aria-label="Notifications">${icon('bell')}</button><details class="pw-profile"><summary aria-label="Open profile menu"><span class="pw-avatar">${initials(displayName)}</span><span class="pw-profile-name">${esc(displayName)}</span>${icon('chevron-down')}</summary><div class="pw-card pw-profile-popover">${!admin?link('My profile','/portal#profile','','user-round'):''}${button('Sign out','pw-logout','','log-out')}${button('Sign out of all devices','pw-logout-all','','shield-check')}</div></details></div></header><main class="pw-content" id="pw-main"><header class="pw-page-header"><div><p class="pw-overline">${admin?'School workspace':'Your journey'} / ${esc(page[1])}</p><h1 class="pw-title-reveal">${esc(admin&&key==='dashboard'?'Your school at a glance':!admin&&key==='dashboard'?'Hello, '+displayName+'.':page[1])}</h1><p class="pw-helper">${esc(page[4])}</p></div><div id="pw-primary"></div></header><div id="pw-page" class="pw-section-body">${skeleton()}</div><footer class="pw-helper">${link('Need help? Chat on WhatsApp','https://wa.me/2348136037074','','message-circle')}</footer></main></div>${!admin?`<nav class="pw-bottom-nav" aria-label="Quick navigation">${studentModules.filter(item=>['dashboard','journey','payments','messages'].includes(item[0])).map(item=>`<a href="#${item[0]}" ${item[0]===key?'aria-current="page"':''}>${icon(item[2])}${esc(item[0]==='journey'?'Journey':item[1])}</a>`).join('')}<a href="#profile">${icon('user-round')}Profile</a></nav>`:''}</div>`;
 action('pw-collapse',()=>{const collapsed=!document.body.classList.contains('pw-collapsed');document.body.classList.toggle('pw-collapsed',collapsed);localStorage.setItem('pw-sidebar-collapsed',String(collapsed));root.querySelector('#pw-collapse')?.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');});action('pw-mobile-menu',()=>menu(true));action('pw-close-menu',()=>{menu(false);(root.querySelector('#pw-mobile-menu') as HTMLElement)?.focus();});action('pw-scrim',()=>menu(false));action('pw-global-search',searchModules);action('pw-logout',()=>signOut());action('pw-logout-all',()=>signOut(true));action('pw-notifications',notifications);menu(false);globalBindings();
}
async function notifications(){const element=dialog('Your updates',skeleton(),true);try{const rows=await service.list(admin?'announcements':'notifications',admin);element.querySelector('.pw-grid')?.remove();const content=element.querySelector('.pw-card.pw-skeleton');if(content)content.outerHTML=rows.length?`<ul class="pw-timeline">${rows.map(row=>`<li>${icon('bell')}<div><strong>${esc(row.title)}</strong><small>${esc(row.body?new DOMParser().parseFromString(row.body,'text/html').body.textContent:'Published school information')}</small></div></li>`).join('')}</ul>`:empty('You’re all caught up','School updates will appear here.');}catch(error){element.querySelector('.pw-skeleton')!.outerHTML=alert('Updates unavailable',errorMessage(error),'danger');}}
export async function renderWorkspace(target:HTMLElement){root=target;const request=++version;admin=location.pathname==='/admin';let profile:any;try{identity=await service.session();if(identity.role==='APPLICANT'){location.replace('/applicant');return;}if((identity.role==='ADMIN')!==admin){location.replace(identity.role==='ADMIN'?'/admin':'/portal');return;}if(!admin)profile=await api('/portal/profile');}catch(error){if(error instanceof ApiError&&error.status===401){location.replace(admin?'/admin/login':'/student/login');return;}target.innerHTML=`<div class="pw"><main class="pw-content">${alert('Your workspace could not be opened',errorMessage(error),'danger')}${link('Try again',location.href)}</main></div>`;return;}if(request!==version)return;currentKey=location.hash.slice(1)||'dashboard';const alias:Record<string,string>={studentAccess:'students',registrationPayments:'payments',adminUsers:'users',posts:'announcements',accessAudit:'audit',idSettings:'settings',applications:admin?'applications':'journey',announcements:admin?'announcements':'messages'};currentKey=alias[currentKey]||currentKey;shell(currentKey,profile);primaryAction=undefined;const targetPage=root.querySelector<HTMLElement>('#pw-page')!;
 try{if(admin&&!readAccess(currentKey)){targetPage.innerHTML=empty('You do not have access to this page','Ask your school owner to review your permissions.');return;}if(currentKey==='dashboard')await dashboard(targetPage,profile,request);else if(!admin)await studentPage(currentKey,targetPage,profile,request);else if(currentKey==='hostels')await hostelPage(targetPage,request);else if(currentKey==='announcements')await announcementsPage(targetPage,request);else if(currentKey==='messages')await messagesPage(targetPage,context(request),true);else if(currentKey==='roles')await rolesPage(targetPage);else if(currentKey==='settings')await settingsPage(targetPage);else await adminTable(currentKey,targetPage,request);}catch(error){if(request===version)fail(targetPage,error);}
}
async function dashboard(target:HTMLElement,profile:any,request:number){
 if(!admin){const [journey,payments,enrolments,bookings,messages,fees,notices]=await Promise.all([api('/portal/journey'),service.list('payments',false),service.list('exams',false),service.list('bookings',false),service.list('messages',false),service.list('fees',false),service.list('notifications',false).catch(()=>[])]);if(request!==version)return;const stage=['Registered','Documents','Application','Offer','Next chapter'];const index=Math.max(0,stage.findIndex(item=>String(journey.journeyStage).toLowerCase().includes(item.toLowerCase())));
 const due=openBalance(fees,payments,'NGN');const unread=notices.filter((row:any)=>!row.readAt).length;const exams=enrolments.filter((row:any)=>row.status!=='CANCELLED').map((row:any)=>row.exam).filter(Boolean);const nextExam=exams.slice().sort((a:any,b:any)=>new Date(a.opensAt||a.closesAt||'2999-01-01').getTime()-new Date(b.opensAt||b.closesAt||'2999-01-01').getTime())[0];const examWhen=(exam:any)=>exam?(exam.opensAt||exam.closesAt||exam.createdAt)?new Date(exam.opensAt||exam.closesAt||exam.createdAt).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Scheduled':'None yet';const booked=bookings.some(row=>['HELD','CONFIRMED','CHECKED_IN'].includes(row.status));target.innerHTML=loaded(`<section class="pw-card pw-feature student-welcome"><div><p class="pw-overline">YOUR NEXT STEP · STUDENT ID ${esc(profile.studentId)}</p><h2>${index===0?'Start with your documents':'Review your next step'}</h2><p class="pw-helper">${index===0?'Start by adding your documents. Your admissions team will help you from there.':'Review your latest application and messages from the school.'}</p></div>${link(index===0?'Manage documents':'View my journey','#'+(index===0?'documents':'journey'),'','arrow-right')}</section><nav class="student-quick-actions" aria-label="Student shortcuts">${link('Explore programmes','#exams','','graduation-cap')}${link('My documents','#documents','','folder-open')}${link('School fees','#payments','','credit-card')}${link('Message admissions','#messages','','message-circle')}</nav><div class="pw-grid four">${stat('Fees due',due.charged===0n?'No fees published':money(due.due,'NGN'),'Indicative · the school confirms your statement','credit-card')}${stat('Exam preparation',String(exams.length),nextExam?nextExam.name||'Enrolled':'No preparation enrolments yet.','graduation-cap')}${stat('Hostel',booked?'Booked':'Not booked','Accommodation status','building-2')}${stat('Unread messages',String(unread),unread?'Waiting for you':'You have read all your updates','message-circle')}</div>${card('A clear route, at every step.',`<ol class="pw-stepper">${stage.map((item,i)=>`<li class="${i<=index?'done':''}">${i<index?icon('circle-check'):''}<strong>${String(i+1).padStart(2,'0')}</strong><p>${item}</p></li>`).join('')}</ol>`)}<div class="pw-grid">${card('Your latest messages',messages.length?`<ul class="pw-timeline">${messages.slice(0,3).map(row=>`<li>${icon('message-circle')}<div><strong>${esc(row.subject)}</strong><small>${esc(row.messages?.at(-1)?.body||'Open your messages to reply.')}</small></div></li>`).join('')}</ul>`:empty('No messages yet','Your admissions team is here to help.',link('Send a message','#messages')))}${card('Your student record',`<dl class="pw-detail-grid"><div><dt>Name</dt><dd>${esc(profile.firstName+' '+profile.lastName)}</dd></div><div><dt>Email</dt><dd>${esc(profile.user?.email)}</dd></div><div><dt>Journey stage</dt><dd>${esc(journey.journeyStage)}</dd></div><div><dt>Student ID</dt><dd>${esc(profile.studentId)}</dd></div></dl>`,link('Edit profile','#profile'))}</div>`);setPrimary('My journey',()=>location.hash='journey','route');return;}
 const summary=await api('/admin/dashboard');const [payments,students,activity,rooms,bookings,applications]=await Promise.all([readAccess('payments')?service.list('payments'):[],readAccess('students')?service.list('students'):[],readAccess('audit')?service.list('audit'):[],readAccess('rooms')?service.list('rooms'):[],readAccess('bookings')?service.list('bookings'):[],readAccess('applications')?service.list('applications'):[]]);if(request!==version)return;
 const revenue=summary.revenue||[];const headline=revenue.find(row=>row.currency==='NGN');const pending=payments.filter(row=>['PENDING','INITIALIZED'].includes(row.status));const newStudents=students.filter(row=>Date.now()-new Date(row.createdAt).getTime()<30*86400000).length;const months=Array.from({length:6},(_,i)=>{const now=new Date();return new Date(now.getFullYear(),now.getMonth()-5+i,1);});const amounts=months.map(month=>payments.filter(row=>row.status==='SUCCESS'&&row.currency==='NGN'&&new Date(row.verifiedAt||row.createdAt).getMonth()===month.getMonth()&&new Date(row.verifiedAt||row.createdAt).getFullYear()===month.getFullYear()).reduce((sum,row)=>sum+Number(row.amountMinor||0)/100,0));const max=Math.max(1,...amounts);
 const recent=payments.filter(row=>row.status==='SUCCESS'&&row.currency==='NGN'&&Date.now()-new Date(row.verifiedAt||row.createdAt).getTime()<=90*864e5);const recentRevenue=recent.reduce((sum,row)=>sum+Number(row.amountMinor||0)/100,0);const beds=rooms.reduce((sum,room)=>sum+Number(room.capacity||0),0);const occupied=bookings.filter(row=>['CONFIRMED','CHECKED_IN'].includes(String(row.status))).length;const occupancy=beds?Math.round(occupied/beds*100):null;const openEnquiries=applications.filter(row=>['SUBMITTED','UNDER_REVIEW','NEEDS_DOCUMENTS'].includes(String(row.status))).length;
 target.innerHTML=loaded(`<div class="pw-grid ${occupancy===null&&!readAccess('applications')?'four':'five'}">${stat('New students',newStudents,'Last 30 days · latest 100 records','users')}${stat('Revenue, 90 days',money(String(Math.round(recentRevenue*100)),'NGN'),'Verified NGN payments · last 90 days','wallet')}${stat('Pending payments',pending.length,'Within the latest 100 transactions','clock')}${occupancy===null?stat('Hostel occupancy','No rooms yet','Add rooms to see bed occupancy','building-2'):stat('Hostel occupancy',occupancy+'%',occupied+' of '+beds+' beds in use','building-2')}${readAccess('applications')?stat('Open enquiries',openEnquiries,'Applications waiting on a decision','file-check'):''}</div><div class="pw-grid dashboard">${card('Revenue, at a glance',`<div class="pw-row"><strong class="pw-price">${esc(money(String(Math.round(amounts.reduce((a,b)=>a+b,0)*100)),'NGN'))}</strong><span class="pw-helper">Recent recorded NGN payments</span></div><svg class="pw-chart" viewBox="0 0 600 220" role="img" aria-label="NGN revenue grouped by month from loaded payment records"><line x1="0" y1="180" x2="600" y2="180"/>${amounts.map((amount,i)=>`<rect x="${i*100+26}" y="${180-(amount/max*135)}" width="42" height="${amount?amount/max*135:2}" rx="5"/><text x="${i*100+47}" y="210" text-anchor="middle">${months[i].toLocaleString('en',{month:'short'})}</text>`).join('')}</svg><p class="pw-helper">Based on the latest 100 transactions. This is not a term billing report.</p>`,badge('Live records'))}${card('Needs your attention',pending.length?`<div class="pw-stack">${pending.slice(0,4).map(row=>`<a class="pw-list-divider" href="#payments"><div class="pw-row">${badge(row.status)}<strong>${esc(money(row.amountMinor,row.currency))}</strong></div><p class="pw-helper">${esc(row.payerEmail||row.reference)}</p></a>`).join('')}</div>`:empty('Everything in view','No pending payments in the records available to you.','', 'circle-check'))}</div><div class="pw-grid">${card('Recent activity',activity.length?`<ul class="pw-timeline">${activity.slice().sort((a,b)=>new Date(b.at).getTime()-new Date(a.at).getTime()).slice(0,5).map(row=>`<li><span class="pw-stat-icon">${icon('check-check')}</span><div><strong>${esc(String(row.action).replaceAll('_',' ').toLowerCase())}</strong><small>${esc(row.entity)} · ${date(row.at)}</small></div></li>`).join('')}</ul>`:empty('A fresh start','School activity will appear here as records are updated.'))}${card('School snapshot',`<div class="pw-list-divider pw-row"><span>University applications</span><strong>${esc(summary.applicants??0)}</strong></div><div class="pw-list-divider pw-row"><span>Exam enrolments</span><strong>${esc(summary.enrolments??0)}</strong></div><div class="pw-list-divider pw-row"><span>Upcoming consultations</span><strong>${esc(summary.upcomingConsultations??0)}</strong></div><div class="pw-list-divider pw-row"><span>Recorded revenue, all time</span><strong>${esc(money(headline?._sum?.amountMinor||'0','NGN'))}</strong></div><p class="pw-helper">Open enquiries are counted from the application pipeline. A dedicated enquiry and term-reporting endpoint is not available yet.</p>`)}</div>`);
 setPrimary(readAccess('students')?'View students':'Refresh overview',()=>readAccess('students')?location.hash='students':renderWorkspace(root),'arrow-up-right');
}
